// ── NURTURE DECLARATION (TEMPORAL v1 · Step 7.1) ─────────────────────────
// CANONICAL. Snapshotted into each site by scripts/sync-cole-lib.mjs.
//
// THE PREMISE THIS FILE ENCODES
// `unresolvable` means we cannot compute a LEGAL deadline. It has never meant
// "no email". Both live products are unresolvable, and both should still be
// nurtured. The nurture track is anchored to the CUSTOMER'S OWN ACTION — the day
// they saved a result, or the day they bought — so it is deadline-free by
// construction and needs no resolver, no jurisdiction date, no countdown.
//
// A SEPARATE LANE, DELIBERATELY. `nurture` sits alongside `temporal` in the
// product config and is independent of it. Four combinations are all legitimate:
//     temporal resolvable + nurture   → both lanes run
//     temporal unresolvable + nurture → the nurture lane carries the product
//     temporal resolvable, no nurture → deadline reminders only
//     neither                          → silent, by declaration
//
// NO GLOBAL DEFAULT. A product without a `nurture` block gets NO nurture track.
// A track is a decision someone made about a specific product's customers, not
// something a product inherits by existing — the same principle as 6.3, applied
// to the other lane. Silence stays the safe default on both.

export type NurtureAnchor =
  | "lead"       // the customer saved a calculator result (/api/leads)
  | "purchase";  // the customer bought (the Stripe webhook)

export interface NurtureDeclaration {
  /**
   * Stable identifier for the cadence+copy pairing, e.g. "standard_v1".
   * Recorded so a later copy revision is a NEW track rather than a silent
   * change to what past customers were sent.
   */
  track: string;
  /**
   * Day offsets from the anchor event. [3, 7, 14] reproduces the historic
   * hardcoded cadence exactly.
   *
   * Each milestone must have COPY. That is validated on the site side (the
   * templates live there), not here — a milestone with no template would
   * otherwise queue a row that can never render, which the send cron would then
   * skip as unresolvable. Declaring a cadence you have no copy for is a
   * declaration error, surfaced loudly, never a silent non-send.
   */
  milestones: number[];
  anchor: NurtureAnchor;
}

/**
 * A product's nurture lane: a LIST of tracks, each with its own anchor.
 *
 * A product may run a lead track AND a purchase track. Each fires from its own
 * path — /api/leads for lead, the Stripe webhook for purchase — and each path
 * selects ONLY the tracks matching its own anchor. The filter is per-track, so a
 * track still cannot double-fire: there is no path that queues a track whose
 * anchor it does not own.
 */
export type NurtureLane = NurtureDeclaration[];

/**
 * List-level validation: the rules that only make sense across tracks.
 * Per-track shape is validateNurture() below.
 */
export function validateNurtureLane(lane: NurtureLane): string[] {
  const problems: string[] = [];
  if (!Array.isArray(lane) || lane.length === 0) {
    return ["nurture must be a non-empty array of tracks"];
  }

  // AT MOST ONE TRACK PER ANCHOR. Two lead tracks would both fire on the same
  // lead save, queueing two sets of rows with identical trigger dates for one
  // recipient — every pair then collides under the 24h cap and drains a day at a
  // time. That is a self-inflicted stall, not a cadence. One track per anchor
  // keeps "each fires from its own path" literally true.
  const byAnchor = new Map<string, number>();
  for (const t of lane) byAnchor.set(t.anchor, (byAnchor.get(t.anchor) ?? 0) + 1);
  for (const [anchor, count] of byAnchor) {
    if (count > 1) problems.push(`${count} tracks declare anchor "${anchor}" — at most one per anchor`);
  }

  // Track names identify what a customer was sent. Two tracks sharing a name
  // would make that record ambiguous.
  const names = new Map<string, number>();
  for (const t of lane) names.set(t.track, (names.get(t.track) ?? 0) + 1);
  for (const [name, count] of names) {
    if (count > 1) problems.push(`track name ${JSON.stringify(name)} used ${count} times — names must be unique within a product`);
  }

  lane.forEach((t, i) => {
    for (const p of validateNurture(t)) problems.push(`track[${i}] (${t.track ?? "unnamed"}): ${p}`);
  });
  return problems;
}

/** The tracks a given path owns. The per-track filter that makes double-firing impossible. */
export function tracksForAnchor(lane: NurtureLane | null | undefined, anchor: NurtureAnchor): NurtureLane {
  return (lane ?? []).filter(t => t.anchor === anchor);
}

/**
 * Shape validation only — copy availability is checked site-side (see above).
 * Returns [] when valid; otherwise every problem found, so one emit reports all
 * of them rather than one-per-run.
 */
export function validateNurture(n: NurtureDeclaration): string[] {
  const problems: string[] = [];

  if (!n.track || typeof n.track !== "string") {
    problems.push("track must be a non-empty string");
  }
  if (n.anchor !== "lead" && n.anchor !== "purchase") {
    problems.push(`anchor must be "lead" or "purchase" (got ${JSON.stringify(n.anchor)})`);
  }
  if (!Array.isArray(n.milestones) || n.milestones.length === 0) {
    problems.push("milestones must be a non-empty array of day offsets");
    return problems;   // the checks below all assume an array
  }
  for (const m of n.milestones) {
    if (!Number.isInteger(m) || m < 1) {
      problems.push(`milestone ${JSON.stringify(m)} must be a positive whole number of days`);
    }
  }
  // Strictly ascending catches BOTH duplicates and out-of-order in one rule.
  // Duplicates matter: two rows on the same day for one recipient would be
  // deferred by the 24h cap and eventually cap_starved — a self-inflicted stall.
  for (let i = 1; i < n.milestones.length; i++) {
    if (n.milestones[i] <= n.milestones[i - 1]) {
      problems.push(`milestones must be strictly ascending (${n.milestones[i - 1]} then ${n.milestones[i]})`);
    }
  }
  return problems;
}

/** The email_type for a milestone. `nurture_d3` for 3 — identical to the historic values. */
export function nurtureEmailType(milestoneDays: number): string {
  return `nurture_d${milestoneDays}`;
}
